    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address callee, bytes memory _data) public {
        // Get the owner before the call
        address ownerBefore = address(c); // No public getter, but we don't need it - we check balance
        // Actually, there is no public getter for owner, so we check a different invariant
        // The only public state is nothing, but we can check that forward doesn't revert on success
        // Instead, we check that after a successful call, the contract still exists
        // Since we can't read owner, we check that the contract's code size is unchanged
